#!/usr/bin/env node
const fs = require('fs');
const path = require('path');

const worktreesDir = path.join(__dirname, '..', '.city-worktrees');

if (!fs.existsSync(worktreesDir)) {
  console.log('Worktrees: 0 total, 0 valid, 0 orphaned');
  process.exit(0);
}

const dirs = fs.readdirSync(worktreesDir).filter(d => fs.statSync(path.join(worktreesDir, d)).isDirectory());
let valid = 0, orphaned = 0;
const list = [];

dirs.forEach(dir => {
  const gitFile = path.join(worktreesDir, dir, '.git');
  const isValid = fs.existsSync(gitFile);
  isValid ? valid++ : orphaned++;
  list.push({dir, valid: isValid});
});

if (process.argv.includes('--list')) {
  list.forEach(({dir, valid}) => console.log(`${dir} ${valid ? 'valid' : 'orphaned'}`));
} else {
  console.log(`Worktrees: ${dirs.length} total, ${valid} valid, ${orphaned} orphaned`);
}

